import Foundation

/// A folder a build tool fills and can fill again.
public struct BuildArtifact: Sendable, Identifiable, Hashable {
    public let path: String
    /// The project it belongs to, by folder name.
    public let project: String
    public let projectPath: String
    /// What produced it, for example "node_modules" or "target".
    public let kind: String
    public let tool: LocalizedStringResource
    public let size: Int64
    /// When the project itself was last touched.
    public let projectModified: Date?
    /// Regenerated by one command, so removing it costs only time.
    public let isSafe: Bool

    public var id: String { path }

    // The tool's name is a localized resource, which has no equality of its own; the path
    // identifies an artifact anyway.
    public static func == (lhs: Self, rhs: Self) -> Bool { lhs.path == rhs.path }

    public func hash(into hasher: inout Hasher) { hasher.combine(path) }
}

/// Finds build output inside projects, which no cache cleaner reaches because it
/// lives in the project folders rather than in the Library.
///
/// Everything here can be rebuilt by the tool that made it. The catch is that a folder
/// called `build` or `dist` holds generated files in one project and hand-written ones in
/// another, so a kind counts as safe only when the file that proves a build tool owns it
/// sits in the same project.
public enum ProjectBuilds {
    public struct Kind: Sendable {
        let directory: String
        /// A file in the project root that proves a build tool owns the directory.
        let marker: String?
        let tool: LocalizedStringResource
        let isSafe: Bool
    }

    public static let kinds: [Kind] = [
        Kind(directory: "node_modules", marker: "package.json", tool: "npm, yarn or pnpm", isSafe: true),
        Kind(directory: "target", marker: "Cargo.toml", tool: "Cargo (Rust)", isSafe: true),
        Kind(directory: ".build", marker: "Package.swift", tool: "Swift Package Manager", isSafe: true),
        Kind(directory: "DerivedData", marker: nil, tool: "Xcode", isSafe: true),
        Kind(directory: "__pycache__", marker: nil, tool: "Python", isSafe: true),
        Kind(directory: ".pytest_cache", marker: nil, tool: "pytest", isSafe: true),
        Kind(directory: ".next", marker: "package.json", tool: "Next.js", isSafe: true),
        Kind(directory: ".nuxt", marker: "package.json", tool: "Nuxt", isSafe: true),
        Kind(directory: ".turbo", marker: "package.json", tool: "Turborepo", isSafe: true),
        Kind(directory: ".gradle", marker: nil, tool: "Gradle", isSafe: true),
        Kind(directory: "Pods", marker: "Podfile", tool: "CocoaPods", isSafe: true),
        Kind(directory: ".venv", marker: nil, tool: "Python virtual environment", isSafe: true),
        Kind(directory: "venv", marker: nil, tool: "Python virtual environment", isSafe: true),
        // Generic names: a project may keep sources under them, so they are never preselected.
        Kind(directory: "build", marker: "package.json", tool: "a build tool", isSafe: false),
        Kind(directory: "dist", marker: "package.json", tool: "a build tool", isSafe: false),
    ]

    /// Where projects usually live, relative to the home folder.
    public static let defaultRoots = [
        "Developer", "Projects", "projects", "Code", "code", "src", "Documents", "Desktop",
    ]

    /// Folders never worth walking into, whatever they contain.
    static let skipped: Set<String> = [
        "Library", "Applications", ".Trash", "node_modules", ".git", "Pods", "DerivedData",
    ]

    public static func scan(
        roots: [String]? = nil,
        home: URL = FileManager.default.homeDirectoryForCurrentUser,
        depth: Int = 4,
        protected: ProtectedPaths = .current()
    ) async -> [BuildArtifact] {
        let directories = roots ?? defaultRoots.map { home.appending(path: $0).path(percentEncoded: false) }
        var found: [BuildArtifact] = []
        for directory in directories where FileManager.default.fileExists(atPath: directory) {
            found += await walk(directory, depth: depth)
        }
        return found.filter { !protected.covers($0.path) }.sorted { $0.size > $1.size }
    }

    /// Descends until a build folder is found, then stops: nothing inside one is interesting.
    private static func walk(_ directory: String, depth: Int) async -> [BuildArtifact] {
        guard depth > 0 else { return [] }
        let fileManager = FileManager.default
        guard let names = try? fileManager.contentsOfDirectory(atPath: directory) else { return [] }
        let present = Set(names)

        var found: [BuildArtifact] = []
        var descend: [String] = []
        for name in names {
            let path = "\(directory)/\(name)"
            var isDirectory: ObjCBool = false
            guard fileManager.fileExists(atPath: path, isDirectory: &isDirectory), isDirectory.boolValue,
                  !isSymlink(path)
            else { continue }

            if let kind = kinds.first(where: { $0.directory == name }),
               kind.marker.map(present.contains) ?? true {
                found.append(BuildArtifact(
                    path: path,
                    project: (directory as NSString).lastPathComponent,
                    projectPath: directory,
                    kind: name,
                    tool: kind.tool,
                    size: await DiskUsage.allocatedSize(of: path) ?? 0,
                    projectModified: modified(of: directory),
                    isSafe: kind.isSafe
                ))
            } else if !skipped.contains(name), !name.hasPrefix(".") {
                descend.append(path)
            }
        }
        for path in descend {
            found += await walk(path, depth: depth - 1)
        }
        return found
    }

    private static func isSymlink(_ path: String) -> Bool {
        let values = try? URL(filePath: path).resourceValues(forKeys: [.isSymbolicLinkKey])
        return values?.isSymbolicLink == true
    }

    private static func modified(of path: String) -> Date? {
        try? URL(filePath: path).resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate
    }
}
